+  fresh();
+  exDrivers.sync([{ slot: 2, name: 'Binh' }], -1);
+  exDrivers.update(1000, 0.016);
+  assert.equal(exDrivers.slotState(2), null, 'chưa có mẫu thì chưa hiện');
